import json, sys, time, urllib.request, urllib.error, base64

BASE = "http://127.0.0.1:4723"
UDID = "37BAB6AB-5179-44EA-B26E-C58BCD5D8D72"
SIDF = "/var/folders/vl/g_dyzwvs4_52rz0rdks_3j900000gp/T/opencode/sid_el"

def req(method, path, body=None, timeout=300):
    url = BASE + path
    data = json.dumps(body).encode() if body is not None else None
    r = urllib.request.Request(url, data=data, method=method, headers={"Content-Type": "application/json"})
    try:
        with urllib.request.urlopen(r, timeout=timeout) as resp:
            return json.loads(resp.read().decode())
    except urllib.error.HTTPError as e:
        return {"error": e.code, "body": e.read().decode()[:2000]}

def get_sid():
    try:
        sid = open(SIDF).read().strip()
        r = req("GET", f"/session/{sid}")
        if "error" not in r:
            return sid
    except Exception:
        pass
    caps = {
        "platformName": "iOS",
        "appium:automationName": "XCUITest",
        "appium:udid": UDID,
        "appium:bundleId": "im.vector.app",
        "appium:noReset": True,
        "appium:shouldTerminateApp": False,
        "appium:autoLaunch": True,
        "appium:autoAcceptAlerts": True,
        "appium:newCommandTimeout": 600,
        "appium:wdaLaunchTimeout": 240000,
        "appium:wdaStartupRetries": 4,
    }
    res = req("POST", "/session", {"capabilities": {"alwaysMatch": caps}})
    sid = res.get("value", {}).get("sessionId")
    if not sid:
        print("SESSION FAIL:", json.dumps(res)[:2000]); sys.exit(1)
    open(SIDF, "w").write(sid)
    return sid

def main():
    cmd = sys.argv[1]
    sid = get_sid()
    if cmd == "source":
        r = req("GET", f"/session/{sid}/source")
        out = r.get("value", "")
        open("/var/folders/vl/g_dyzwvs4_52rz0rdks_3j900000gp/T/opencode/el_source.xml", "w").write(out)
        print(out[:6000])
    elif cmd == "tap":
        r = req("POST", f"/session/{sid}/element", {"using": "accessibility id", "value": sys.argv[2]})
        eid = (r.get("value") or {}).get("element-6066-11e4-a52e-4f735466cecf")
        if not eid:
            r = req("POST", f"/session/{sid}/element", {"using": "-ios predicate string", "value": sys.argv[2]})
            eid = (r.get("value") or {}).get("element-6066-11e4-a52e-4f735466cecf")
        if not eid:
            print("NOT FOUND"); sys.exit(1)
        print(req("POST", f"/session/{sid}/element/{eid}/click"))
    elif cmd == "taptxt":
        r = req("POST", f"/session/{sid}/element", {"using": "-ios predicate string", "value": f"label == '{sys.argv[2]}'"})
        eid = (r.get("value") or {}).get("element-6066-11e4-a52e-4f735466cecf")
        if not eid:
            print("NOT FOUND"); sys.exit(1)
        print(req("POST", f"/session/{sid}/element/{eid}/click"))
    elif cmd == "hold":
        r = req("POST", f"/session/{sid}/element", {"using": "-ios predicate string", "value": sys.argv[2]})
        eid = (r.get("value") or {}).get("element-6066-11e4-a52e-4f735466cecf")
        if not eid:
            print("NOT FOUND"); sys.exit(1)
        print(req("POST", f"/session/{sid}/wda/element/{eid}/touchAndHold", {"duration": float(sys.argv[3]) if len(sys.argv) > 3 else 1.5}))
    elif cmd == "holdxy":
        print(req("POST", f"/session/{sid}/wda/touchAndHold", {"x": float(sys.argv[2]), "y": float(sys.argv[3]), "duration": float(sys.argv[4]) if len(sys.argv) > 4 else 1.5}))
    elif cmd == "tapxy":
        print(req("POST", f"/session/{sid}/wda/tap", {"x": float(sys.argv[2]), "y": float(sys.argv[3])}))
    elif cmd == "mobile":
        args = json.loads(sys.argv[3]) if len(sys.argv) > 3 else {}
        print(req("POST", f"/session/{sid}/execute/sync", {"script": f"mobile: {sys.argv[2]}", "args": [args]}))
    elif cmd == "shot":
        r = req("GET", f"/session/{sid}/screenshot")
        open(sys.argv[2], "wb").write(base64.b64decode(r.get("value", "")))
        print("saved", sys.argv[2])
    elif cmd == "sleep":
        time.sleep(float(sys.argv[2]))

main()

